background-clip: padding-box;
}
td {
border: 1px solid lightgray;
padding: 4px;
}
.table-blot-wrapper {
position: relative;
}
.active-cell {
outline: 1px solid #066fa9;
background: rgba(193, 214, 253, 0.3);
}
.menu-placeholder {
position: absolute;
background: #dad7d7;
top: 50%;
transform: translateY(-50%);
right: 2px;
visibility: hidden;
z-index:1;
border-radius: 3px;
cursor: pointer;
}
.active-cell .menu-placeholder {
visibility:visible;
}
.cell-content {
line-height: 22px;
outline: none;
min-width: 120px;
min-height: 40px;
padding: 10px 0 10px 5px;
}
.table-operations-menu {
position: absolute;
width: 225px;
min-height: 100px;
top: 25px;
border-radius: 5px;
visibility: hidden;
padding: 10px 5px 10px 10px;
background: #fff;
box-shadow: -2px 2px 7px 0 rgba(0, 0, 0, 0.5);
}
.table-operations-menu-item {
padding: 4px 0;
cursor:pointer;
font-weight: normal;
}
.table-operations-menu-item img {
margin-right: 4px;
vertical-align: -4px;
}
.table-operations-menu-item.no-image {
padding-left: 24px;
}
.border-bottom {
border-bottom: 1px solid #dad7d7;
padding-bottom: 10px !important;
margin-bottom: 10px;
}
.set-background input {
width:14px;
height: 14px;
margin-right: 10px;
vertical-align: -2px;
cursor: pointer;
}
.color-box {
display: inline-block;
width: 20px;
height: 20px;
background: #f0f0f0;
border: solid 1px #dad7d7;
margin-left: 10px;
border-radius: 2px;
vertical-align: -4px;
}
.background-active {
background: #f0f0f0 !important;
outline: 1px solid #d7d7d7;
}
.text-format-item {
